// Кейс: .qa/tests/monitoring/MON-032.md · план: .qa/e2e-app/specs/app.md (1.46)
// Android, «בדיקת בטיחות», режим вибрации + медиа низко: строка «עוצמת צפצוף מקסימלית» объясняет, что нужно выйти из вибрации/беззвучного
// (не только «увеличьте громкость»), «המשך» серая; после перехода на звонок + максимум и «בדיקה חוזרת» — строка просит тестовый звук.
// Режим звонка и громкость выставляются по adb и ВОЗВРАЩАЮТСЯ. Тестовый звук НЕ запускается («השמעה» не нажимается) — тест тихий.
import { assert, openSafetyCheck, withAudio } from '../lib.mjs';

export const name = 'Android «בדיקת בטיחות»: режим вибрации + медиа низко → «…אם הטלפון במצב רטט או שקט — העבירו אותו למצב צלצול…», «המשך» серая; звонок + максимум → «בדיקה חוזרת» → «השמיעו את צליל הבדיקה…» #8edb6e @android @app @prod-safe';

export default async function (app) {
  await withAudio(app, { mode: 'VIBRATE', media: 4 }, async ({ max }) => {
    await openSafetyCheck(app);

    // 1. Вибрация + медиа низко: подсказка про режим звонка. Допустимы оба текста: текущий (универсальный) и из следующей сборки
    // («הטלפון במצב רטט — העבירו אותו למצב צלצול כדי שהאזעקה תישמע»); общее для обоих — «העבירו אותו למצב צלצול».
    const hint = await app.waitFor('העבירו אותו למצב צלצול', {
      timeout: 20000,
      what: 'подсказка «…העבירו אותו למצב צלצול…» в строке «עוצמת צפצוף מקסימלית» (режим VIBRATE, медиа 4 — выставлены по adb)',
    });
    assert(/רטט/.test(hint.text + hint.desc), 'в подсказке названо состояние «רטט» (вибрация)');
    assert(!(await app.exists('השמיעו את צליל הבדיקה ואשרו ששמעתם אותו')), 'вместо подсказки нет обычной строки «השמיעו את צליל הבדיקה…»');

    // 2. «המשך» серая (⚠ блокирует — решение пользователя 08.10, Figma 07.2).
    await app.waitEnabled('המשך', false, { timeout: 5000, what: '«המשך» при ⚠ по громкости/режиму' });

    // 3. Пользователь переключил на звонок и поднял медиа → «בדיקה חוזרת» → обычная строка с тестовым звуком, ⚠ нет.
    await app.setRingerMode('NORMAL');
    await app.setMediaVolume(max);
    await app.tap('בדיקה חוזרת', { what: '«בדיקה חוזרת»' });
    await app.waitFor('השמיעו את צליל הבדיקה ואשרו ששמעתם אותו', { timeout: 20000, what: 'строка «השמיעו את צליל הבדיקה…» после «בדיקה חוזרת» (звонок + медиа max)' });
    assert(!(await app.exists('העבירו אותו למצב צלצול')), 'подсказка про режим звонка исчезла');
  });
  await app.restart(); // выход без запуска мониторинга
}
